import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"wake-server","description":"Every wake-server command that manages a Wake installation, with its exit codes, its environment and the variables the installer reads.","frontmatter":{"description":"Every wake-server command that manages a Wake installation, with its exit codes, its environment and the variables the installer reads."},"headers":[],"relativePath":"reference/wake-server.md","filePath":"reference/wake-server.md","lastUpdated":1794486787000}'),r={name:"reference/wake-server.md"};function s(n,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="wake-server" tabindex="-1">wake-server <a class="header-anchor" href="#wake-server" aria-label="Permalink to &quot;wake-server&quot;">​</a></h1><p><code>wake-server</code> manages an installation: it lives in the installation&#39;s directory, and the installer puts a command of the same name on your <code>PATH</code>. Run <code>wake-server --help</code> for its usage.</p><p>Run <code>wake-server</code> as the user who installed it, never with <code>sudo</code>. If the command is not found, run <code>&lt;your installation directory&gt;/wake-server</code>, or add <code>~/.local/bin</code> to your <code>PATH</code> (see <a href="/wake-dist/docs/reference/troubleshooting#on-the-server">Troubleshooting</a>).</p><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>wake-server start</code></td><td>Start Wake as installed, opening Docker Desktop first on macOS when Docker is not running; waits until Wake is healthy. See <a href="/wake-dist/docs/run/start-stop">Start and stop</a></td></tr><tr><td><code>wake-server stop</code></td><td>Stop Wake; containers, volumes, backups and settings are kept</td></tr><tr><td><code>wake-server status</code></td><td>Show the version, the people the free plan counts, the backups, each service&#39;s health and the newest release. See <a href="/wake-dist/docs/run/status">Status</a></td></tr><tr><td><code>wake-server upgrade [--version vX.Y.Z] [--log &lt;file&gt;]</code></td><td>Back up, then move to the newest stable release or to <code>vX.Y.Z</code>; roll back, data included, when the new version is not healthy; then keep the newest <code>WAKE_UPGRADE_BACKUPS</code> upgrade backups. See <a href="/wake-dist/docs/run/upgrade">Upgrade</a></td></tr><tr><td><code>wake-server backup</code></td><td>Write a backup of the database, the evidence files and <code>.env</code> to <code>backups/</code> while Wake keeps serving. See <a href="/wake-dist/docs/run/backup">Back up and restore</a></td></tr><tr><td><code>wake-server restore &lt;backup&gt;</code></td><td>Replace the data with a backup&#39;s, after backing up the current data; Wake stops while it runs, and <code>.env</code> is kept. <code>&lt;backup&gt;</code> is a full path or one relative to the current directory. See <a href="/wake-dist/docs/run/backup#restore">Restore</a></td></tr><tr><td><code>wake-server accounts</code></td><td>List the accounts and the people the free plan counts. See <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a></td></tr><tr><td><code>wake-server accounts disable &lt;email&gt;</code></td><td>Sign an account out and free its place, keeping its history</td></tr><tr><td><code>wake-server accounts enable &lt;email&gt;</code></td><td>Give a disabled account back while a place is free</td></tr><tr><td><code>wake-server auto-upgrade on</code></td><td>Run <code>upgrade</code> daily at 04:17 from your crontab, logging to <code>auto-upgrade.log</code>. See <a href="/wake-dist/docs/run/upgrade#upgrade-on-a-schedule">Upgrade on a schedule</a></td></tr><tr><td><code>wake-server auto-upgrade off</code></td><td>Stop the daily upgrade</td></tr><tr><td><code>wake-server auto-upgrade status</code></td><td>Print <code>on</code> or <code>off</code></td></tr><tr><td><code>wake-server install-cli</code></td><td>Install the <code>wake</code> CLI of this version with npm (Node.js 24 or newer), verified</td></tr></tbody></table><p><code>--log &lt;file&gt;</code> appends all of an upgrade&#39;s output to the file, first moving a file over 1 MiB to <code>&lt;file&gt;.1</code>.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><ul><li><code>0</code>: done, or nothing to do (such as an upgrade that finds Wake up to date).</li><li><code>1</code>: the command failed and says why, such as Docker not running, a refused backup, a rolled-back upgrade, or a second <code>upgrade</code>, <code>backup</code> or <code>restore</code> while one runs.</li><li><code>2</code>: a usage error, such as an unknown command or option, or a missing argument; the usage is printed.</li></ul><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>WAKE_DOCKER_TIMEOUT</code></td><td>Seconds <code>start</code> waits for Docker Desktop on macOS (default 120)</td></tr></tbody></table><p>Settings that change the installation itself, such as <code>WAKE_UPGRADE_BACKUPS</code>, go in its <code>.env</code>; see <a href="/wake-dist/docs/reference/environment#installation-settings">Installation settings</a>.</p><h2 id="the-installer" tabindex="-1">The installer <a class="header-anchor" href="#the-installer" aria-label="Permalink to &quot;The installer&quot;">​</a></h2><p><code>install.sh</code> takes the options in <a href="/wake-dist/docs/run/install-options#options">Install options</a> and reads these variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>WAKE_BIN_DIR</code></td><td>Where the <code>wake-server</code> command goes (default <code>$HOME/.local/bin</code>)</td></tr><tr><td><code>WAKE_OPEN_COMMAND</code></td><td>The program that opens the browser at the end (default <code>open</code> on macOS, <code>xdg-open</code> on Linux)</td></tr></tbody></table>',13)])])}const k=t(r,[["render",s]]);export{p as __pageData,k as default};
